import heapq


def nearestHospital(n, roads, src, hospitals):
    target = set(hospitals)
    adj = [[] for _ in range(n)]
    for a, b, w in roads:
        adj[a].append((b, w))
    best = [float('inf')] * n
    best[src] = 0
    heap = [(0, src)]
    while heap:
        d, u = heapq.heappop(heap)
        if d > best[u]:
            continue
        if u in target:
            return d
        for v, w in adj[u]:
            nd = d + w
            if nd < best[v]:
                best[v] = nd
                heapq.heappush(heap, (nd, v))
    return -1
